css:
.loader {
  position: relative;
  width: 46px;
  height: 52px;
}
.loader::before {
  content: "";
  position: absolute;
  bottom: 2px;
  left: 50%;
  width: 16px;
  height: 6px;
  margin-left: -8px;
  border-radius: 2px;
  background: #6366f1;
}
.loader i {
  position: absolute;
  bottom: 6px;
  left: 50%;
  width: 4px;
  height: 40px;
  margin-left: -2px;
  border-radius: 2px;
  background: #6366f1;
  transform-origin: bottom center;
  animation: swing 1.2s ease-in-out infinite;
}
.loader i::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 50%;
  width: 11px;
  height: 11px;
  margin-left: -5.5px;
  border-radius: 50%;
  background: #6366f1;
}
@keyframes swing {
  0%, 100% { transform: rotate(-28deg); }
  50% { transform: rotate(28deg); }
}
